/*
 * A047992  Number of distinct permutations generated by shuffling n cards
 *          with "clump size" <= 2.
 * https://oeis.org/A047992
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 2*Fibonacci(n+1) for n>3, with a(2)=2, a(3)=5. Fibonacci
 *            here is the standard F(1)=1, F(2)=1, F(3)=2,
 * Range:     u8 n <= 10, u16 n <= 22, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* No other includes are necessary; the build supplies seq_t and idx_t. */
seq_t a(idx_t n)
{
    /* Handle the special lower‑offset values. */
    if (n == (idx_t)2)
        return (seq_t)2;
    if (n == (idx_t)3)
        return (seq_t)5;

    /* Compute Fibonacci(n+1) iteratively. */
    seq_t f_prev = (seq_t)0;   /* F(0) */
    seq_t f_curr = (seq_t)1;   /* F(1) */
    idx_t k = n + (idx_t)1;    /* Target index for Fibonacci */

    /* For n>3 we already have k>=5, so the loop will run at least once. */
    for (idx_t i = (idx_t)2; i <= k; ++i)
    {
        seq_t f_next = f_prev + f_curr;
        f_prev = f_curr;
        f_curr = f_next;
    }

    /* Return 2 * F(n+1). */
    return f_curr * (seq_t)2;
}
